    pub fn new(coder_url: &str, reviewer_url: &str) -> Self {
        let client = Client::builder()
            .timeout(Duration::from_secs(120))
            .build()
            .expect("Failed to build reqwest client");
        Self { client, coder_url: coder_url.to_string(), reviewer_url: reviewer_url.to_string() }
    }

    pub async fn generate(&self, url: &str, prompt: String, max_length: usize, temperature: f32) -> Result<String> {
        let request = GenerateRequest { prompt, max_length, temperature };
        let response = self.client.post(url).json(&request).send().await.context("Failed to send")?;
        let body = response.text().await.context("Failed to read body")?;
        let parsed: GenerateResponse = serde_json::from_str(&body).context("Failed to parse")?;
        let text = parsed.text.or(parsed.generated_text).unwrap_or_default();
        if text.is_empty() { return Err(anyhow::anyhow!("Empty response")); }
        Ok(text)
    }
}
